import { Component } from "react";
function getItemPrice(price){
    return price >3000 ? 'expensive' : 'cheap'
}

function getItemName(item){
    return ` this is ${item.name} which is ${this.getItemPrice(item.price)}`;
}

function Cars(){
    const items = [
        {
            name: 'audi',
            price: 20000
        },
        {
            name: 'bmw',
            price: 30000
        },
        {
            name: 'merc',
            price: 40000
        }
    ]

    return <>
    {
        this.items.map((item,index)=>{
            return `${index+1}. ${this.getItemName(item)}`
        })
    }
    </>
}

export default Cars;
